import React, { useState } from "react";
import axios from "axios";

const PredictionPage = () => {
  const [formData, setFormData] = useState({
    age: "",
    mmse: "",
    cdr: "",
    hippocampusVolume: "",
    entorhinalVolume: "",
    ventriclesVolume: "",
    apoe4: "",
    educationYears: "",
    gender: "",
    brainVolume: ""
  });

  const [modelType, setModelType] = useState("rf");
  const [prediction, setPrediction] = useState(null);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handlePredict = async () => {
    const inputData = [
      Number(formData.age),
      Number(formData.mmse),
      Number(formData.cdr),
      Number(formData.hippocampusVolume),
      Number(formData.entorhinalVolume),
      Number(formData.ventriclesVolume),
      Number(formData.apoe4),
      Number(formData.educationYears),
      Number(formData.gender),
      Number(formData.brainVolume)
    ];

    try {
      const response = await axios.post("http://localhost:5000/predict", {
        inputData,
        modelType
      });
      setPrediction(response.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
    } catch (error) {
      console.error("Prediction error:", error);
      setPrediction("Prediction failed");
    }
  };

  return (
    <div style={{ padding: "2rem" }}>
      <h2>Alzheimer's Prediction</h2>
      {Object.entries(formData).map(([key, value]) => (
        <div key={key}>
          <label>{key.replace(/([A-Z])/g, " $1")}</label>
          <input
            type="number"
            name={key}
            value={value}
            onChange={handleChange}
            required
          />
        </div>
      ))}
      <div>
        <label>Model Type: </label>
        <select value={modelType} onChange={(e) => setModelType(e.target.value)}>
          <option value="rf">Random Forest</option>
          <option value="svm">SVM</option>
          <option value="cnn">CNN</option>
        </select>
      </div>
      <button onClick={handlePredict}>Predict</button>
      {prediction && <h3>Result: {prediction}</h3>}
    </div>
  );
};

export default PredictionPage;
